// api.jsx (Corrected for maximum compatibility)

export function askAIStream(inputText) {
  // Simulated streaming (replace with real API later)
  const fakeResponse = "Hello, I am Mene Bot — I can help you with anything!";
  const chunks = fakeResponse.split(" ");
  let index = 0;

  // Manually implement the async iterator protocol to avoid compiler errors
  return {
    async next() {
      // 1. Check if the stream is finished
      if (index >= chunks.length) {
        return { done: true };
      }

      // 2. Simulate delay using await
      await new Promise((r) => setTimeout(r, 150));
      
      // 3. Get the next chunk and advance the index
      const chunk = chunks[index++] + " ";

      // 4. Return the value
      return { value: chunk, done: false };
    },
    // This makes the object compatible with the while loop in Chatbot.jsx
    [Symbol.asyncIterator]() {
      return this;
    }
  };
}


